-- Guarda md5 por fila sobre el texto anterior; si no cuadran 49 actualizadas = 49 en el historial, ROLLBACK de todo.
BEGIN;
CREATE TEMP TABLE te (id int, antes_md5 text, despues text, nueva_calidad text) ON COMMIT DROP;
INSERT INTO te VALUES
(15, '052a18bb0ea000c279c3ae795b7f5def', 'La respuesta correcta es D) Hematoma subdural. La TC muestra una colección extraaxial en forma de semiluna que se extiende a lo largo de la convexidad cerebral. Al estar por debajo de la duramadre, el hematoma subdural puede cruzar las líneas de sutura (no cruza la hoz ni el tentorio). Es típico de pacientes anticoagulados o antiagregados, a menudo tras traumatismos mínimos, y en su forma subaguda o crónica puede dar solo alteraciones cognitivas o del lenguaje, sin focalidad motora. El hematoma epidural (C) tiene forma biconvexa o lenticular y no cruza las suturas, porque la duramadre está firmemente adherida a ellas. La hemorragia subaracnoidea (A) ocupa surcos y cisternas basales, sin formar una colección periférica. El hematoma intraparenquimatoso (B) se sitúa dentro del tejido cerebral, no entre este y la calota.', 'revisada'),
(28, '3a1c77d16eec89eaf09aebd7a441a42d', 'La respuesta correcta es D) Aumento de la utilización de citrulina por los enterocitos: es el cambio que no se produce. Los enterocitos no consumen citrulina, la fabrican: a partir de la glutamina, el glutamato y la prolina sintetizan citrulina, que pasa a la sangre y utiliza sobre todo el riñón para formar arginina. Tras una comida rica en proteínas y pobre en hidratos de carbono sí ocurren los otros tres cambios: el músculo esquelético oxida los aminoácidos de cadena ramificada, que el hígado apenas capta (A); los aminoácidos estimulan la secreción de glucagón, que con poca glucosa no queda contrarrestada por la insulina (B); y el hígado aumenta la gluconeogénesis a partir de los esqueletos carbonados de los aminoácidos para mantener la glucemia (C).', 'revisada'),
(32, '694ccf677d4189aecafa4da9250ac0b7', 'La respuesta correcta es D) El flujo de corriente en la profundidad de la fibra muscular es similar al de la motoneurona: es la afirmación incorrecta. La fibra muscular es tan gruesa que la corriente del potencial de acción apenas llega a su interior; para despolarizar las miofibrillas profundas necesita los túbulos T, invaginaciones de la membrana que llevan el potencial de acción hacia dentro y activan la liberación de calcio del retículo sarcoplásmico. El axón de la motoneurona no tiene ese sistema. Las otras afirmaciones son ciertas: el potencial de reposo es parecido en ambas, de unos −80 a −90 mV (A); el potencial de acción del músculo dura de 1 a 5 ms, unas cinco veces más que el de las fibras nerviosas mielinizadas grandes (B); y la velocidad de conducción en el músculo es de 3 a 5 m/s, muy inferior a la de las fibras A alfa, de 70 a 120 m/s (C).', 'revisada'),
(50, '0688bd15e1509c39ed48c5a6de4c5bc7', 'La respuesta correcta es A) Empaglifozina. En un diabético tipo 2 con cardiopatía isquémica que no está en objetivo con metformina (HbA1c 8,3 %), las guías recomiendan añadir un fármaco con beneficio cardiovascular demostrado: un inhibidor de SGLT2 como la empagliflozina, que redujo la mortalidad cardiovascular en el ensayo EMPA-REG, o un agonista de GLP-1. Además aporta un descenso modesto de la presión arterial y del peso. La glipizida (B), una sulfonilurea, no tiene beneficio cardiovascular y produce hipoglucemias y aumento de peso. La acarbosa (C) tiene una eficacia glucémica escasa y mala tolerancia digestiva. La sitagliptina (D), un inhibidor de la DPP-4, es neutra en eventos cardiovasculares y, al actuar sobre la vía de las incretinas, se usa con precaución en pacientes con antecedente de pancreatitis.', 'revisada'),
(55, 'fbfde4e3fcdfc0e09a33898bc1ae7c52', 'La respuesta correcta es B) Metformina. El uso prolongado de metformina reduce la absorción de vitamina B12 en el íleon terminal: interfiere con la absorción del complejo B12-factor intrínseco, que depende del calcio, y el déficit aumenta con la dosis y los años de tratamiento. Por eso se recomienda medir periódicamente la B12 en tratamientos largos, sobre todo si aparece neuropatía o anemia macrocítica, que pueden confundirse con complicaciones de la propia diabetes. La gliclazida (A, sulfonilurea), la repaglinida (C, meglitinida) y la pioglitazona (D, glitazona) no interfieren en la absorción de la vitamina B12, por lo que no justifican esa determinación.', 'revisada'),
(91, '73139eec175947296b6be3153563287b', 'La respuesta correcta es C) Recaída psicótica al suspender el tratamiento tras un primer episodio psicótico. En psiquiatría, la neuroimagen se pide cuando hay sospecha de causa orgánica, y en el primer episodio psicótico ya se habrá hecho. Una recaída tras abandonar el antipsicótico es la evolución esperable de la enfermedad ya diagnosticada y, si el cuadro es igual al primero, no aporta datos nuevos que obliguen a repetirla. En cambio, sí son indicaciones de neuroimagen un trastorno mental que debuta después de los 50 años, por la mayor probabilidad de tumor, ictus o demencia (A); la asociación de crisis convulsivas y síntomas psiquiátricos, que sugiere una lesión cerebral (B); y los síntomas atípicos, como alteración de la conciencia o focalidad, que orientan a un origen orgánico (D).', 'revisada'),
(149, 'f7c2884d4f041d85d3a3f0f9193915ee', 'La respuesta correcta es D) Nefritis intersticial aguda. El antecedente de un nuevo fármaco (ciprofloxacino) seguido, una semana después, de mal estado general, artralgias, rash cutáneo y caída del filtrado glomerular es el cuadro clásico de nefritis intersticial aguda de mecanismo inmunoalérgico farmacológico, con las manifestaciones sistémicas (rash, artralgias) reflejando la reacción de hipersensibilidad. La glomerulonefritis postinfecciosa (A) no explica el pródromo alérgico ni la ausencia de un foco infeccioso claro previo a la introducción del fármaco; la pielonefritis aguda (C) queda descartada por la ausencia de nitritos y de clínica infecciosa activa; y la nefrotoxicidad directa del ciprofloxacino (B) es infrecuente y no explicaría las manifestaciones sistémicas de hipersensibilidad.', NULL),
(175, '9255b85433dace9da20215366e1008e2', 'La respuesta correcta es B) Antimoniato de meglumina intralesional. Una placa eritemato-anaranjada en la cara que crece despacio tras una picadura y acaba ulcerándose con escamocostra, en alguien que vive en la costa mediterránea, es una leishmaniasis cutánea localizada, transmitida por el flebótomo; el tratamiento anti-TNF (adalimumab) favorece la infección. En una lesión única y pequeña, el tratamiento de elección son los antimoniales pentavalentes por vía intralesional, que evitan la toxicidad sistémica. La isotretinoína oral (A) es un tratamiento del acné y no actúa sobre el parásito. Los corticoides sistémicos (C) empeorarían la infección al aumentar la inmunosupresión. La amoxicilina oral (D) no tiene actividad frente a Leishmania y solo trataría una sobreinfección bacteriana que el caso no describe.', 'revisada'),
(177, 'fc05f0bf5816daf16236358facc63ca4', 'La respuesta correcta es A) Metronidazol IV. Una cavidad única con nivel hidroaéreo en el segmento superior del lóbulo inferior derecho, en un alcohólico con malas condiciones de higiene, es un absceso pulmonar por aspiración: una infección polimicrobiana por anaerobios de la boca y estreptococos microaerófilos y aerobios. El metronidazol en monoterapia es el menos eficaz porque, aunque cubre bien los anaerobios estrictos, no actúa sobre esos estreptococos, y tiene tasas de fracaso elevadas. La clindamicina (B) y la asociación de un betalactámico con un inhibidor de betalactamasas, como amoxicilina-clavulánico (C), cubren tanto anaerobios como estreptococos y son de elección; el moxifloxacino (D) es una alternativa eficaz, con buena actividad frente a ambos y buena biodisponibilidad oral.', 'revisada'),
(188, 'b46ed1e143c235ffb2e535e61e1cd80c', 'La respuesta correcta es C) Miocardiopatía hipertrófica. El dato clave es un soplo sistólico en el borde paraesternal izquierdo que aumenta con la maniobra de Valsalva: el Valsalva reduce el retorno venoso y el tamaño del ventrículo izquierdo, lo que aumenta la obstrucción dinámica del tracto de salida en la miocardiopatía hipertrófica obstructiva. Con esa maniobra la mayoría de los soplos disminuyen; solo el del prolapso mitral se alarga, pero se oye en el ápex y no explica la disnea de esfuerzo con un ECG patológico. La estenosis aórtica (B) da un soplo en el foco aórtico que disminuye con el Valsalva. La insuficiencia mitral (D) también disminuye y se oye en el ápex, irradiada a la axila. La insuficiencia tricuspídea (A) aumenta con la inspiración (signo de Rivero-Carvallo), no con el Valsalva.', 'revisada'),
(197, '3cd2ff80b36b1bc86432938928224ab8', 'La imagen macroscópica (izquierda) muestra una mucosa colónica inflamada, congestiva y desflecada con aspecto granuloso característico. Las imágenes histopatológicas revelan infiltración densa de células inflamatorias (linfocitos, plasmocitos) en la lámina propia y submucosa, con distorsión de la arquitectura glandular normal y presencia de criptas inflamadas. Este patrón histológico es típico de colitis ulcerosa, donde la inflamación es predominantemente mucosa y submucosa, afectando continuamente el colon. Las formaciones polipoides visibles corresponden a islotes de mucosa regenerada entre áreas de ulceración, no a verdaderos pólipos neoplásicos. La ausencia de hallazgos sugestivos de infección parasitaria, masas linfoides localizadas (linfoma) o la distribución difusa y continua de la inflamación descarta las otras opciones. El diagnóstico es colitis ulcerosa.', NULL),
(202, 'b840290abe2c47825014314b7d31b424', 'La respuesta correcta es D) El único hallazgo anormal es el acúmulo patológico del radiotrazador en el tumor costal conocido. La gammagrafía muestra captación intensa en la lesión de la 5.ª costilla izquierda y, en el resto del esqueleto, captación simétrica en las fisis de crecimiento, normal en un niño de 13 años; no hay otros focos. Por eso no es una gammagrafía normal (A), ya que la costilla tumoral capta, ni hay afectación metastásica diseminada (C). La opción B es falsa: el sarcoma de Ewing sí metastatiza en hueso y médula ósea, además de en el pulmón, y por eso el estudio de extensión incluye la valoración de todo el esqueleto, con gammagrafía ósea o, cada vez más, con PET-TC.', 'revisada'),
(222, 'b47449cd3f10176fb707685c903a2bce', 'La respuesta correcta es C) Inmunoterapia específica subcutánea con extracto de Apis mellifera al 100%. Un apicultor con anafilaxia por picadura de abeja y sensibilización demostrada al veneno (pruebas cutáneas e IgE específica positivas) tiene indicación de inmunoterapia con veneno de abeja, el único tratamiento etiológico: modifica la respuesta inmunitaria y protege frente a nuevas reacciones sistémicas en la gran mayoría de los pacientes, algo especialmente importante por su exposición laboral constante. Los autoinyectores de adrenalina (A) son imprescindibles para tratar una reacción si ocurre, y los antihistamínicos, broncodilatadores y corticoides (B) son medidas de apoyo, pero ninguno actúa sobre la causa. La ciclosporina oral (D) no tiene indicación en la alergia a himenópteros.', 'revisada'),
(251, 'f9fe36a29dd63344fcfbe6fea549776d', 'La respuesta correcta es A) La vaginosis bacteriana es habitualmente una infección monomicrobiana — esta es la afirmación INCORRECTA. La vaginosis bacteriana es, por definición, una disbiosis vaginal POLIMICROBIANA (sustitución de la microbiota normal dominada por Lactobacillus por una mezcla de anaerobios como Gardnerella vaginalis, Prevotella, Mobiluncus, entre otros), no una infección monomicrobiana. Las demás opciones son correctas: la candidiasis vulvovaginal es la infección vulvovaginal más prevalente en Europa (B), el umbral de vulvovaginitis candidiásica recidivante se sitúa en torno a los 3-4 episodios anuales según la fuente (C), y la vaginosis bacteriana asintomática habitualmente no requiere tratamiento farmacológico salvo en contextos específicos (D).', NULL),
(253, '797ac6cc57c2a32c16a91d2b6ba79304', 'La respuesta correcta es D) Cuando se produzca una bradicardia fetal que no se recupera tras el cese de la contracción y la fontanela menor se encuentra pasado el III plano de Hodge. Para aplicar una ventosa hacen falta una indicación, como la sospecha de pérdida del bienestar fetal que supone una bradicardia mantenida, y unas condiciones, sobre todo una presentación cefálica de vértice encajada, como mínimo en el III plano de Hodge. La opción D reúne las dos. En A la presentación está en el II plano, demasiado alta para un parto instrumental, y 2 horas de expulsivo en una primigesta con epidural todavía no se consideran prolongadas. En B la cabeza está sobre el estrecho superior, sin encajar, y una hemorragia con repercusión fetal obliga a una cesárea. En C el punto guía es el mentón, es decir, una presentación de cara, en la que la ventosa está contraindicada.', 'revisada'),
(297, '4efba93a568d6927077db9ddf7d9ce73', 'La respuesta correcta es D) Colocación de un clavo endomedular acerrojado. Una metástasis lítica que afecta a todo el diámetro de la diáfisis humeral y causa dolor continuo tiene un riesgo muy alto de fractura patológica (la escala de Mirels suma puntos por lesión lítica, dolor funcional y afectación de más de dos tercios de la cortical). Con una supervivencia esperada de más de 2 años está indicada la estabilización profiláctica, que en la diáfisis del húmero se hace con un clavo endomedular acerrojado: alivia el dolor y permite usar el brazo, y después se completa con radioterapia. La actitud expectante (A) no es válida: aunque el húmero no soporta peso, las cargas de rotación y de las actividades diarias bastan para fracturarlo. Los mórficos a dosis altas (B) no eliminan el riesgo de fractura ni el dolor mecánico. Un yeso (C) no estabiliza una lesión de este tamaño ni es tolerable a largo plazo.', 'revisada'),
(303, '2cfef8001a682d5c5983f6af69f26e9f', 'La respuesta correcta es C) Suspender temporalmente el acenocumarol y reanudar la anticoagulación cuando se haya alcanzado el intervalo terapéutico, calculando de nuevo la dosis. Un INR elevado sin ningún sangrado se maneja de forma ambulatoria: se suspenden temporalmente las dosis, se controla el INR en pocos días y se reanuda el anticoagulante con una dosis semanal ajustada; según el nivel de INR y el riesgo hemorrágico se puede añadir vitamina K oral a dosis bajas. En un portador de una válvula mecánica mitral hay que evitar revertir del todo la anticoagulación, por el riesgo de trombosis protésica. Por eso no está indicada la vitamina K intravenosa a dosis altas y repetidas (A), ni el complejo protrombínico o el plasma (D), que se reservan para hemorragias graves. Tampoco hace falta derivarlo al hospital (B) si no sangra.', 'revisada'),
(330, '445d6ff0d2c637e2d548666faa638229', 'La respuesta correcta es C) Mielosis funicular. El cuadro de astenia, parestesias, tez amarillenta (ictericia leve por eritropoyesis ineficaz/hemólisis intramedular) y anemia macrocítica (VCM 120) con pérdida de sensibilidad vibratoria y posicional es característico del déficit de vitamina B12, que produce degeneración combinada subaguda de cordones posteriores y vías piramidales (mielosis funicular). La mielopatía cervicoartrósica (A) no se asocia a anemia macrocítica. La mielitis necrosante subaguda (B) cursa con un cuadro inflamatorio agudo, no con anemia megaloblástica. La mielopatía de la EM (D) no explica la anemia macrocítica ni la ictericia.', NULL),
(388, '60baab06a1f6bf319d4ce983d52a6ba8', 'La respuesta correcta es C) Neumonía por SARS-CoV 2 con síndrome de distrés respiratorio agudo. El paciente tiene una neumonía con PCR positiva para SARS-CoV-2, infiltrados bilaterales periféricos y una PaO2/FiO2 de 250. Según la definición de Berlín, un cuadro agudo con infiltrados bilaterales no explicados por insuficiencia cardiaca y una PaO2/FiO2 de 300 o menos es un SDRA, que se gradúa como leve (200-300), moderado (100-200) o grave (100 o menos); este paciente tiene un SDRA leve, una complicación frecuente de la neumonía por COVID-19. La hemorragia pulmonar (A) cursaría con hemoptisis y caída de la hemoglobina, que no se describen. Una neumonía bacteriana sobreañadida (B) suele dar una consolidación lobar, no un patrón alveolointersticial periférico bilateral típico de la infección viral. La hipoventilación alveolar (D) produce hipercapnia con un gradiente alveolo-arterial normal y no se acompaña de infiltrados pulmonares.', 'revisada'),
(389, 'ea3bf30d3cb9b5c831b5a282ccef75f3', 'La respuesta correcta es A) Neumonitis por hipersensibilidad. Se recomienda retirar humidificador y control evolutivo. Los síntomas empeoraron tras empezar a usar un humidificador nocturno, cuya agua contaminada por hongos o bacterias es una fuente clásica de antígenos inhalados. La neumonitis por hipersensibilidad encaja con el resto de datos: crepitantes finos en las bases, patrón restrictivo en la espirometría (FVC baja con FEV1/FVC de 0,92) e infiltrados reticulares subpleurales y parcheados en la TC. El primer paso es retirar el antígeno y vigilar la evolución. El reflujo (B) puede dar tos, pero no crepitantes, restricción ni infiltrados. Una crisis asmática (C) daría un patrón obstructivo, no restrictivo, y no explicaría la afectación intersticial. La alergia al perro (D) produciría rinitis o asma, pero convive con él desde hace 5 años y el empeoramiento coincide con el humidificador.', 'revisada'),
(395, 'cc4ee5fa797fec4e86f0908ccf3d4ec2', 'La respuesta correcta es C) Se visualiza afectación en mama izquierda y axilar ipsilateral. La PET-TC con 18F-FDG muestra captación patológica en el tumor de la mama izquierda y en la axila izquierda, lo que indica afectación ganglionar regional; no hay focos que indiquen metástasis a distancia, por lo que la opción D es falsa. Las opciones A y B tampoco son correctas: en un carcinoma triple negativo de alto grado con ganglios axilares afectados, el tratamiento de inicio no es la cirugía sino la quimioterapia neoadyuvante (hoy asociada a inmunoterapia), que mejora el pronóstico y permite valorar la respuesta; y la biopsia selectiva del ganglio centinela no está indicada de entrada cuando ya hay afectación axilar.', 'revisada'),
(397, '7199197948f4994e3db59373cdf0be32', 'La respuesta correcta es D) RM con contraste. Schwannoma vestibular. La imagen es una RM con gadolinio en la que se ve una lesión bien delimitada que capta contraste en el ángulo pontocerebeloso derecho. Junto con una hipoacusia neurosensorial unilateral progresiva y acúfenos, es el cuadro típico del schwannoma vestibular, el tumor más frecuente del ángulo pontocerebeloso, que nace de la vaina del nervio vestibular en el conducto auditivo interno. El meningioma (A) también puede aparecer ahí, pero suele tener una base de implantación dural ancha y no entra en el conducto auditivo; además, la imagen es una RM con contraste, no sin él. El epidermoide (B) no capta contraste y se estudia con RM en difusión, no con TC. Un tumor glial (C) es intraaxial, dentro del parénquima, no en el ángulo pontocerebeloso.', 'revisada'),
(399, 'd226431acfa759e38ccd3c970ba867b0', 'La respuesta correcta es A) Obstrucción intestinal secundaria a neoplasia estenosante de colon descendente. La TC muestra dilatación del marco cólico con una imagen estenosante en el colon izquierdo. Aunque el paciente tiene antecedentes de carcinoma oral, la carcinomatosis peritoneal es muy rara en este tipo de tumor, de estirpe epidermoide; la obstrucción por migración de la sonda de gastrostomía sería extremadamente improbable, al requerir atravesar el píloro y la válvula ileocecal, y la obstrucción funcional sería menos probable sin signos previos de íleo paralítico.', NULL),
(444, '0238dd8a082196b427b55b1c49bd8577', 'La respuesta correcta es D) El tipo histológico más frecuente es el carcinoma epidermoide y su tratamiento quirúrgico asocia habitualmente disección ganglionar cervical. El carcinoma epidermoide (carcinoma de células escamosas) representa más del 90% de los cánceres de lengua, y su tratamiento de referencia es la resección quirúrgica del tumor primario, que requiere casi siempre disección ganglionar cervical electiva o terapéutica dado el alto riesgo de metástasis linfáticas cervicales (presente en el 20-40% de los casos al diagnóstico). El carcinoma basocelular es excepcional en la lengua y la radioterapia es tratamiento adyuvante, no primario (descarta A). El VPH sí se relaciona con el cáncer de lengua/orofaringe, pero la irradiación solar no es factor etiológico relevante en la mucosa oral (descarta B). El cáncer de lengua tiene alta tendencia a la metástasis linfática cervical, lo que justifica la disección ganglionar sistemática (descarta C).', NULL),
(451, '57a6fc400ed463076ee78694f7410b82', 'La respuesta correcta es D) Disfonía por tensión muscular. El cuadro de un profesor universitario (uso vocal profesional intenso) con disfonía crónica progresiva, voz áspera y forzada, cansancio y fatiga vocal, sin lesión orgánica visible en las cuerdas vocales, y con una hiperfunción/compresión supraglótica objetivada como disminución del diámetro anteroposterior del vestíbulo laríngeo durante la fonación, es la descripción clásica de la disfonía por tensión muscular (muscle tension dysphonia), un trastorno funcional muy frecuente en profesionales de la voz caracterizado precisamente por ese patrón de constricción supraglótica en la videoendoscopia. La "distonía de la musculatura extrínseca laríngea" no es una entidad diagnóstica estandarizada equivalente; las distonías laríngeas reconocidas (disfonía espasmódica) afectan a la musculatura intrínseca y cursan con interrupciones fónicas intermitentes, no con el patrón continuo de fatiga y compresión supraglótica descrito aquí (descarta B y C). La parálisis abductora cursaría con estridor y compromiso respiratorio, no con este cuadro (descarta A).', NULL),
(455, '45bbcb49db366d4a05d08798930f1d18', 'El leiomioma tipo 1 según la clasificación FIGO 2011 es un mioma **submucoso** (protruye hacia la cavidad uterina), que por su localización en cara anterior y con Doppler periférico de alta resistencia, es la causa más probable del sangrado y la menorragia que refiere la paciente. Los miomas submucosos son responsables de metrorragias y sangrado intermenstrual al afectar directamente el endometrio y la vascularización local. Dado que los estudios de coagulación y hemograma son normales (descartando coagulopatías), y que el mioma es accesible por vía histeroscópica, la derivación a la consulta de histeroscopias es el procedimiento diagnóstico y terapéutico de primera línea, permitiendo tanto confirmar la lesión como realizar una miomectomía histeroscópica en el mismo acto. La laparoscopia sería innecesaria para una lesión submucosa, y solicitar RMN retrasaría el diagnóstico definitivo cuando ya hay indicación clara de intervención.', NULL),
(467, 'b171c1c4037212d44e5084cb89fb6362', 'La respuesta correcta es B) Frecuencia respiratoria. La puntuación de Apgar valora cinco signos al minuto y a los 5 minutos de vida, cada uno de 0 a 2 puntos: frecuencia cardiaca, esfuerzo respiratorio, tono muscular, respuesta a estímulos (irritabilidad refleja) y color. La respiración se puntúa por el esfuerzo (ausente, débil o irregular, llanto vigoroso), no por la frecuencia respiratoria, que no forma parte del test. Las otras tres opciones sí son componentes del Apgar: la frecuencia cardiaca (A), que puntúa 2 si es mayor de 100 lpm; el tono muscular (C), de la flacidez a los movimientos activos; y el color (D), de la cianosis o palidez generalizada a un recién nacido completamente sonrosado.', 'revisada'),
(521, '886577ace82b06735a51908d6475a91e', 'La respuesta correcta es C) Grado III: Herida contaminada. La clasificación de los CDC incluye en el grado III las heridas accidentales recientes, las cirugías con una falta grave de asepsia o con salida importante de contenido digestivo, y las incisiones en las que se encuentra inflamación aguda no purulenta. Si hay pus, la herida pasa al grado IV, sucia o infectada (D), junto con las heridas traumáticas antiguas con tejido desvitalizado y las vísceras perforadas. El grado I, limpia (A), es una incisión sin inflamación que no abre las vías respiratoria, digestiva ni genitourinaria. El grado II, limpia-contaminada (B), abre esas vías de forma controlada y sin contaminación inusual.', 'revisada'),
(529, '8b1b3f384bc9042408a241a964b1db3f', 'La respuesta correcta es A) Glomerulonefritis de cambios mínimos. Un síndrome nefrótico (proteinuria masiva, albúmina de 2 g/dl y edemas) con sedimento sin hematuria y función renal normal en un paciente con linfoma de Hodgkin recién diagnosticado es la asociación paraneoplásica clásica de la enfermedad de cambios mínimos, ligada probablemente a citocinas liberadas por las células tumorales; suele remitir al tratar el linfoma. La glomerulonefritis membranosa (B) es la glomerulopatía paraneoplásica típica de los tumores sólidos (pulmón, colon, mama), no del Hodgkin. La membranoproliferativa (C) se asocia a infecciones crónicas como la hepatitis C, a crioglobulinemia y a gammapatías monoclonales, y suele cursar con hematuria. La glomeruloesclerosis focal y segmentaria (D) se asocia más a obesidad, VIH o heroína y no es la lesión característica del linfoma de Hodgkin.', 'revisada'),
(533, 'e6fe5a8df7d455fdd325a33ffc181eb4', 'La respuesta correcta es C) Tomografía axial sin y con contraste IV. Un engrosamiento focal de 2,5 cm en la pelvis renal de un varón de 66 años obliga a descartar un tumor urotelial del tracto urinario superior. La prueba indicada es la TC sin y con contraste con fase excretora (uro-TC): la fase sin contraste detecta litiasis, la fase con contraste caracteriza la lesión y la excretora muestra defectos de repleción en la vía urinaria, además de estadificar. La resonancia magnética (A) es una alternativa solo si no se puede usar contraste yodado. La urografía intravenosa (B) ha sido sustituida por la uro-TC, más sensible y que aporta información de los tejidos vecinos. Repetir la ecografía (D) retrasaría el diagnóstico sin caracterizar mejor la lesión.', 'revisada'),
(605, 'af676acf189792c1d3aff28e31e84a74', 'La respuesta correcta es A) Rotura de la porción larga del bíceps braquial. Un dolor brusco con chasquido en el hombro de un varón de 60 años, seguido de un abultamiento en la parte distal del brazo, es la deformidad de «Popeye»: al romperse el tendón de la porción larga, que nace en el tubérculo supraglenoideo de la escápula y discurre por la corredera bicipital, el vientre muscular se retrae hacia el codo. La pérdida de fuerza es escasa porque la porción corta y el braquial anterior siguen flexionando el codo. La rotura de la porción corta (B) es excepcional, porque su origen en la apófisis coracoides es muy resistente. La rotura del tendón distal (C) se produce en el codo, con dolor en la flexura y retracción del vientre hacia el hombro, la deformidad contraria. La rotura del pectoral mayor (D) produce un defecto en el pliegue axilar anterior, no un abultamiento en el brazo.', 'revisada'),
(606, '7c171cd8c4e60fd701f4acb40653c4ca', 'Analizando la imagen y el caso clínico:

**Hallazgos radiográficos clave en la imagen:**
- Telerradiografía que muestra alteraciones en múltiples epífisis (hombros, caderas, rodillas)
- Patrón de afectación bilateral y simétrica de varias articulaciones
- Deformidad de epífisis con aspecto irregular y fragmentado

**Análisis del caso clínico:**
- Paciente con talla baja (característica de displasia epifisaria múltiple)
- Dolor bilateral en caderas desde edades tempranas
- Afectación posterior de hombros durante seguimiento
- Necesidad de artroplastia de cadera izquierda en edad adulta por artrosis secundaria

**Justificación de la respuesta D (Displasia Epifisaria Múltiple):**

La displasia epifisaria múltiple es una condropatía congénita autosómica dominante que afecta múltiples centros de osificación epifisarios de forma bilateral y simétrica (caderas, rodillas, hombros, tobillos). Cursa con talla baja, dolor articular crónico desde la infancia y desarrollo temprano de artrosis secundaria, lo que explica la necesidad de artroplastia en este paciente relativamente joven. La radiografía muestra deformidades epifisarias múltiples características.

Las otras opciones se descartan: Perthes es unilateral habitualmente, epifisiolisis es aguda o subaguda sin patrón multifocal tan evidente, y osteonecrosis multifocal es poco probable como diagnóstico de infancia con esta presentación clínica.', NULL),
(607, 'fa15655c5934238b6d360c47e3fa3dbd', 'La respuesta correcta es D) Osteocondroma. La radiografía muestra una exóstosis que nace de la metáfisis y crece alejándose de la articulación, con cortical y medular en continuidad con las del hueso del que sale: es el aspecto típico del osteocondroma, el tumor óseo benigno más frecuente. Puede doler por roce con tendones o partes blandas, y en un adulto un osteocondroma que duele o crece obliga a vigilar una posible transformación a condrosarcoma. Cuando es solitario es esporádico; la forma hereditaria (autosómica dominante, genes EXT) es la de exostosis múltiples. La osteomielitis (A) daría lisis, reacción perióstica y clínica infecciosa. La osificación heterotópica (B) aparece en partes blandas, separada del hueso, tras traumatismos o cirugías. El encondroma (C) es una lesión intramedular, con calcificaciones en anillos y arcos, no una excrecencia de la superficie.', 'revisada'),
(608, '2bbff54e598b1dc4ba15c6361eab89ee', 'La respuesta correcta es D) Bloqueo AV de tercer grado. Un anciano con mareos y un síncope sin pródromos ni relación con el esfuerzo, con una presión diferencial amplia (110/40 mmHg), orienta a una bradiarritmia. En el ECG, las ondas P y los complejos QRS van disociados, cada uno a su frecuencia, con un ritmo de escape lento: es un bloqueo auriculoventricular completo, indicación de marcapasos definitivo. El bloqueo de primer grado (B) solo alarga el PR, todas las P conducen y no produce síncopes. En el bloqueo de segundo grado tipo II (C) el PR es constante y algunas P dejan de conducir de forma súbita, pero sigue habiendo relación entre P y QRS. Un infarto anterior con elevación del ST (A) daría dolor torácico y elevación del ST en las precordiales, que no se describen.', 'revisada'),
(623, '702c324fd0c1039eb1665dd2ba4c7203', 'La respuesta correcta es C) Disminución de la ureagénesis. Sin acil-CoA deshidrogenasa no se completa la β-oxidación y falta acetil-CoA en el hígado. El acetil-CoA es necesario para fabricar N-acetilglutamato, el activador obligado de la carbamoil-fosfato sintetasa I, primera enzima del ciclo de la urea; por eso baja la ureagénesis y puede aparecer hiperamonemia. Las otras opciones son falsas. Los ácidos grasos que no se oxidan en la mitocondria se desvían a la ω-oxidación, con aumento, no disminución, de ácidos dicarboxílicos en la orina (A). La gluconeogénesis disminuye, no aumenta (B): necesita la energía y el acetil-CoA de la β-oxidación, que activa la piruvato carboxilasa, y por eso aparece hipoglucemia hipocetósica en el ayuno. La carnitina libre disminuye (D), porque queda unida a los acilos que se acumulan y se elimina como acilcarnitinas.', 'revisada'),
(632, 'd8f5053c04899f2589147d7573260ca2', 'La respuesta correcta es D) Lupus eritematoso neonatal – Anticuerpos anti-Sm: es la pareja incorrecta. El lupus neonatal se debe al paso transplacentario de anticuerpos anti-Ro/SSA y anti-La/SSB, que producen lesiones cutáneas, citopenias, alteraciones hepáticas y, lo más grave, bloqueo cardiaco congénito. Los anti-Sm son muy específicos del lupus eritematoso sistémico, pero no se asocian al lupus neonatal. Las otras tres parejas son correctas, porque se trata de anticuerpos IgG que atraviesan la placenta: los anti-desmogleína 3 del pénfigo vulgar materno pueden dar un pénfigo neonatal transitorio (A); los anti-Ro y anti-La causan el bloqueo cardiaco congénito (B); y los anticuerpos anti-receptor de acetilcolina producen una miastenia gravis neonatal transitoria (C).', 'revisada'),
(641, '7e133ea2f39cc0474e7c74818334d266', 'La respuesta correcta es D) La incidencia de SARS-CoV-2 en la población que no usa mascarilla se reduciría un 53% si la utilizara. Un riesgo relativo de 0,47 significa que la incidencia entre quienes usan mascarilla es el 47 % de la de quienes no la usan, es decir, una reducción relativa del riesgo de 1 − 0,47 = 0,53, un 53 %. La opción A confunde el riesgo relativo con la reducción: la incidencia se reduce un 53 %, no un 47 %. La B invierte la comparación de forma incorrecta: si el RR es 0,47, el riesgo de quien no la usa es 1/0,47 ≈ 2,1 veces mayor, es decir, aumenta un 113 %, no un 53 %. La C también toma el 47 % como fracción evitada: la mascarilla evitaría 53 de cada 100 casos que se dan en quienes no la usan, no 47.', 'revisada'),
(657, '141301bdd4b752fd2b93538133abc782', 'La respuesta correcta es A) Sulfato de magnesio vía endovenosa. La preeclampsia puede debutar después del parto, sobre todo en la primera semana. Esta puérpera tiene hipertensión grave (165/100 mmHg en dos tomas), cefalea y transaminasas por encima del doble de lo normal; aunque el cociente proteína/creatinina no llega a 300 mg/g, la afectación hepática y los síntomas neurológicos bastan para diagnosticar una preeclampsia con criterios de gravedad. Las plaquetas (254.000/µL) son normales, así que no es un síndrome HELLP. El tratamiento inmediato de primera línea es el sulfato de magnesio intravenoso para prevenir la eclampsia, junto con antihipertensivos de acción rápida. El labetalol oral (B) no es la vía adecuada para una hipertensión grave, en la que se usa por vía intravenosa, y además no previene las convulsiones. Los corticoides a dosis altas (C) no han demostrado beneficio en la preeclampsia ni en el HELLP posparto. Los diuréticos (D) no están indicados, porque estas pacientes suelen tener el volumen intravascular disminuido; solo se usan si hay edema pulmonar.', 'revisada'),
(673, 'bf6c7e5545cb17233b4aadc9d6952620', 'La respuesta correcta es C) Es frecuente la agregación familiar: es la afirmación incorrecta. Diplopía, ptosis y debilidad proximal que empeoran a lo largo del día, sin afectación pupilar y con reflejos normales, son una miastenia gravis, una enfermedad autoinmune adquirida y casi siempre esporádica; los casos familiares son raros y suelen corresponder a síndromes miasténicos congénitos, que no son autoinmunes. Las otras afirmaciones son ciertas. El título de anticuerpos anti-receptor de acetilcolina no se correlaciona con la gravedad cuando se compara entre pacientes (A). Se asocia con cierta frecuencia a otras enfermedades autoinmunes, sobre todo tiroideas (B). Y los pacientes seropositivos, con anticuerpos anti-receptor de acetilcolina o anti-MuSK, responden mejor al tratamiento inmunosupresor que los seronegativos (D).', 'revisada'),
(710, '3f0842c88f0ad934f962eef8982cc506', 'La respuesta correcta es A) Shouldice. Es una herniorrafia abierta que repara la pared posterior del conducto inguinal con los propios tejidos del paciente, imbricando la fascia transversalis en varios planos con sutura continua, sin malla. Las otras tres técnicas son hernioplastias con malla. En la de Lichtenstein (B), por vía abierta anterior, la malla se fija sobre la fascia transversalis, por debajo de la aponeurosis del oblicuo mayor, y se suturan sus bordes al ligamento inguinal y a la vaina del recto. En la TEP (C) y la TAPP (D), por laparoscopia, la malla se coloca en el espacio preperitoneal: la TEP llega a él sin entrar en el peritoneo y la TAPP lo hace a través de la cavidad abdominal.', 'revisada'),
(719, 'cd2dd28b7ab409760f56d713d6b39e6f', 'La respuesta correcta es D) Tumoración maligna obstructiva de colédoco distal y solicitar TC abdominal. Un anciano con ictericia progresiva, prurito y síndrome tóxico (pérdida de peso, astenia y anorexia) de un mes de evolución, con dilatación de la vía biliar intra y extrahepática y la vesícula distendida (signo de Courvoisier-Terrier), tiene una obstrucción distal de la vía biliar probablemente maligna: cabeza de páncreas, ampolla de Vater o colangiocarcinoma distal. La prueba indicada es la TC abdominal, que localiza la lesión, valora la resecabilidad y estadifica. La colecistitis aguda (A) daría dolor y fiebre, sin dilatación de la vía biliar ni síndrome constitucional de un mes. La coledocolitiasis (B) suele dar cólico biliar e ictericia fluctuante, y la vesícula con litiasis crónica no suele distenderse. La toxicidad por amoxicilina-clavulánico (C) produce colestasis intrahepática sin dilatación de la vía biliar, y el cuadro empezó antes de tomar el antibiótico.', 'revisada'),
(737, 'f1956f281bfa6c45d65f23e71c7a3013', 'La respuesta correcta es B) Linfoma B difuso de célula grande. La biopsia muestra células grandes, muy atípicas, con un patrón de crecimiento difuso, positivas para CD20, un marcador de linfocitos B, y negativas para CD3, CD30, CD15 y citoqueratinas. Ese perfil corresponde a un linfoma B difuso de célula grande; el estudio de CD10, BCL6 y MUM1 sirve para clasificarlo en tipo centrogerminal o no centrogerminal (algoritmo de Hans). El linfoma de Hodgkin clásico (A) tiene células de Reed-Sternberg CD30+ y CD15+, habitualmente CD20 negativas, sobre un fondo inflamatorio. El linfoma T periférico (C) expresaría CD3 y no CD20. Una metástasis de carcinoma (D), incluida la del carcinoma renal previo, sería positiva para citoqueratinas (CKAE1-AE3), que aquí son negativas.', 'revisada'),
(753, 'ec893c24ef5293f4f985272a95bde506', 'La respuesta correcta es A) Si presenta más de tres episodios anuales está indicado realizar profilaxis con un antiviral como valaciclovir 500 mg cada 12 horas o 1 g al día, durante seis meses: es la afirmación incorrecta. La profilaxis antiviral continua del herpes labial recurrente no se indica por tener más de tres brotes al año: se reserva para recurrencias muy frecuentes (habitualmente seis o más al año), brotes graves o complicados (eritema multiforme recurrente, inmunodepresión) o situaciones de riesgo concretas; en los demás casos basta con tratar cada brote precozmente si hace falta. Las otras afirmaciones son correctas. En un brote leve con una sola lesión puede no tratarse o usarse un tratamiento tópico secante, como los fomentos de sulfato de zinc o de cobre (B). Si hay riesgo de afectación ocular se trata por vía oral con antivirales a dosis altas (C). Y la exposición solar es un desencadenante conocido de las recurrencias, por lo que se recomienda fotoprotección labial (D).', 'revisada'),
(754, '959eb648ee25ba78e1525735fbf138f7', 'La respuesta correcta es A) Es una enfermedad de declaración obligatoria. Fiebre, exantema maculopapular generalizado y una escara negra (mancha negra) en un cazador que ha estado en el campo es una fiebre botonosa o exantemática mediterránea, causada por Rickettsia conorii y transmitida por la garrapata del perro. Es una enfermedad sometida a vigilancia epidemiológica y de declaración obligatoria en muchas comunidades autónomas. El tratamiento de elección es la doxiciclina, no la amoxicilina (B), que no es activa frente a las rickettsias. La mayoría de los casos son leves y se tratan de forma ambulatoria, sin necesidad de derivación al hospital (C), que se reserva para las formas graves. La escara aparece primero, en el punto de la picadura, antes o a la vez que la fiebre, y el exantema surge unos días después; por eso no es cierto que la fiebre preceda a la escara (D).', 'revisada'),
(758, '65b7c779f05802cc5710eda49f76495b', 'La respuesta correcta es A) Dímero D. Una paciente con lupus activo que desarrolla disnea aguda tiene un riesgo alto de tromboembolismo pulmonar: el lupus es protrombótico y su TTPA alargado sugiere un anticoagulante lúpico (síndrome antifosfolípido). La primera determinación es el dímero D: si es normal, el TEP es improbable; si está elevado, se confirma con angioTC pulmonar. El test de Coombs (D) ya se hizo, y la hemoglobina ha subido de 5,8 a 10,2 g/dl, así que no hay datos de reactivación de la hemólisis que expliquen la disnea. Las proteínas en orina (B) sirven para vigilar la nefritis lúpica, pero no orientan una disnea aguda. El NT-proBNP (C) valoraría una insuficiencia cardiaca, y la paciente no tiene otros síntomas que la sugieran.', 'revisada'),
(782, 'f33b475a076c4571e3ecebecf15b9af8', 'La respuesta correcta es A) AngioTC helicoidal con contraste. La hipoxemia aguda con taquicardia, fiebre y obnubilación a las 20 horas de una fractura diafisaria de fémur obliga a pensar en un embolismo pulmonar, trombótico o graso. El síndrome de embolia grasa (hipoxemia, alteración neurológica, petequias y trombopenia a las 24-72 horas) es un diagnóstico clínico sin prueba específica, mientras que el tromboembolismo pulmonar sí debe confirmarse o descartarse: la angioTC pulmonar es la prueba con mayor sensibilidad y especificidad para él, y además puede mostrar los infiltrados de la embolia grasa. La gammagrafía de perfusión (B) es menos específica y se reserva para cuando no se puede usar contraste. La radiografía de tórax (C) es poco sensible y a menudo normal al principio. La ecocardiografía (D) valora la repercusión sobre el ventrículo derecho, pero no confirma el diagnóstico.', 'revisada'),
(907, 'e21e8f470512800de878697d5ff92d99', 'La respuesta correcta es C) Edad, sexo, tabaco, presión arterial sistólica, colesterol total y colesterol HDL. SCORE2 estima el riesgo a 10 años de eventos cardiovasculares mortales y no mortales en personas de 40 a 69 años sin enfermedad cardiovascular ni diabetes, con seis variables: edad, sexo, tabaquismo, presión arterial sistólica, colesterol total y colesterol HDL; con los dos lípidos calcula el colesterol no-HDL. España está en la región de bajo riesgo. No usa el colesterol LDL (A), y ni la lipoproteína(a) (B y D) ni los triglicéridos (D) entran en el cálculo, aunque una Lp(a) muy elevada puede usarse para reclasificar el riesgo de forma individual.', 'revisada'),
(938, '33307ce301fb53f248fbeb42eed550c3', 'La respuesta oficial señala **hiponatremia inducida por tiazidas**, y esta es la más razonable según el cuadro clínico presentado.

**Justificación:**

El dato clave es que hace un mes le **cambió el tratamiento antihipertensivo** (presumiblemente se añadió o modificó incluyendo tiazida), y ahora presenta hiponatremia sintomática (astenia, náuseas, cefalea) con osmolalidad plasmática baja (257 mOsm/kg), lo que indica hiponatremia hiposmolar verdadera. El sodio urinario de 45 mEq/L es compatible con una respuesta renal inadecuada. 

Las tiazidas causan hiponatremia mediante dos mecanismos: depleción de volumen (estimulando ADH) y un efecto directo de potenciación de la acción de ADH en el túbulo colector. El cuadro clínico, el timing temporal (cambio de tratamiento hace un mes), la ausencia de signos de insuficiencia suprarrenal aguda (tensión arterial mantenida, potasio normal), la glucemia normal (descarta pseudohiponatremia) y la ausencia de polidipsia de comportamiento hacen que las tiazidas sean el culpable más probable. La creatinina normal también descarta insuficiencia renal significativa.', NULL);
CREATE TEMP TABLE cuenta (n int) ON COMMIT DROP; INSERT INTO cuenta VALUES (0);
CREATE TEMP TABLE h0 AS SELECT count(*) AS n FROM explicaciones_historial;

SET LOCAL mir.motivo = 'Tanda errores 766';
WITH u AS (UPDATE preguntas SET explicacion = 'La respuesta correcta es A) Distrofia oculofaríngea. Ptosis bilateral sin diplopía, disfagia y debilidad proximal de las piernas en un adulto de mediana edad, cuya madre murió por una broncoaspiración (probable disfagia por la misma enfermedad, de herencia autosómica dominante), es el cuadro típico de la distrofia muscular oculofaríngea. La biopsia muestra un patrón miopático con vacuolas ribeteadas y sin inflamación; el hallazgo específico, que confirma el estudio genético del gen PABPN1, son las inclusiones intranucleares tubulofilamentosas. La miositis por cuerpos de inclusión (D) también tiene vacuolas ribeteadas y debilidad del cuádriceps, pero afecta además a los flexores de los dedos, no produce ptosis, no es familiar y la biopsia suele mostrar infiltrado inflamatorio endomisial. La miopatía mitocondrial (B) puede dar ptosis, pero su biopsia muestra fibras rojas rasgadas. La miastenia gravis (C) suele dar diplopía y fluctuación, con CK y biopsia normales.', explicacion_calidad = 'revisada'
  WHERE id = 766 AND md5(explicacion) = '2a112b033bcb2ab661df8dcd7b24def0' AND explicacion_calidad <> 'controversia' RETURNING 1)
UPDATE cuenta SET n = n + (SELECT count(*) FROM u);

SET LOCAL mir.motivo = 'Tanda errores 2026-10';
WITH u AS (UPDATE preguntas p SET explicacion = te.despues, explicacion_calidad = coalesce(te.nueva_calidad, p.explicacion_calidad)
  FROM te WHERE p.id = te.id AND md5(p.explicacion) = te.antes_md5 AND p.explicacion_calidad <> 'controversia' RETURNING 1)
UPDATE cuenta SET n = n + (SELECT count(*) FROM u);

DO $$ DECLARE n int; h int; BEGIN
  SELECT cuenta.n INTO n FROM cuenta;
  SELECT (SELECT count(*) FROM explicaciones_historial) - h0.n INTO h FROM h0;
  IF n <> 49 OR h <> 49 THEN RAISE EXCEPTION 'actualizadas %, historial +% (esperado 49): ROLLBACK de todo', n, h; END IF;
  RAISE NOTICE 'actualizadas %, historial +%', n, h;
END $$;
COMMIT;
